var i=`0892-fish-ambul-thiyal`;var n=`world-0892`;var a=`LK`;var s=`south-asia`;var r=4;var o=59;var l={en:`Fish Ambul Thiyal`,ua:`Амбул тіал із риби`};var u={en:`Fish Ambul Thiyal is a Sri Lanka dish made with yellowfin tuna, yellow onion, fresh curry leaves, tamarind concentrate. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Амбул тіал із риби, страва кухні країни Шрі-Ланка. Основні складники: жовтоперий тунець, жовта цибуля, свіже листя карі, концентрат тамаринду. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 25 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 25 хвилин.`,t:[`marinating`],m:25,i:[[`yellowfin-tuna`,720,`g`],[`ground-black-pepper`,5,`g`],[`ground-turmeric`,4,`g`],[`table-salt`,null,`to_taste`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,170,`g`],[`coconut-oil`,40,`ml`],[`fresh-curry-leaves`,10,`leaf`]]},{en:`Add the tuna to the tangy dark curry and simmer until cooked through; gently reduce so the sauce clings to the pieces.`,ua:`Додайте тунець у кисле темне карі й тушкуйте до повної готовності; обережно уваріть соус, щоб він обгорнув шматочки.`,t:[`braising`],m:22,i:[[`tamarind-concentrate`,65,`g`],[`water`,280,`ml`],[`ground-cinnamon`,3,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,1,`pcs`]]}];var g={slug:i,id:n,country:`LK`,region:s,servings:4,minutes:59,title:l,text:u,steps:h};export{a as country,g as default,n as id,o as minutes,s as region,r as servings,i as slug,h as steps,u as text,l as title};